const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const falta = ['ERPNEXT_DOMAIN', 'ERPNEXT_API_KEY', 'ERPNEXT_API_SECRET'].filter(k => !$env[k]);
if (falta.length) return wfail(500, 'PENDENTE_CONFIGURACAO_RITMO: variáveis ausentes: ' + falta.join(', '));
const b = $input.first().json.body || {};
const op_id = String(b.order_nsu || '').trim();                       // op_id = order_nsu = POS Invoice.synapse_op_id
if (!/^[A-Za-z0-9._-]{1,100}$/.test(op_id)) return wfail(400, 'order_nsu (op_id) ausente ou inválido');
const transaction_nsu = String(b.transaction_nsu || '').trim();       // preservado À PARTE: nunca substitui o op_id
const slug = String(b.invoice_slug || b.slug || '').trim();
if (!transaction_nsu || !slug) return wfail(400, 'Webhook sem transaction_nsu/invoice_slug');
const pago = b.paid_amount ?? b.amount ?? null;
return [{ json: { ok: true, op_id, transaction_nsu, slug, valor_webhook: pago === null ? null : Number(pago), capture_method: b.capture_method || null, payload: JSON.stringify(b).slice(0, 4000) } }];

const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const c = $input.first().json.data || {};
const bad = (m) => wfail(400, m);
if (c.status !== 'conectado') return bad('PENDENTE_CONFIGURACAO_INFINITEPAY: conta InfinitePay não está conectada (status: ' + (c.status || 'desconhecido') + ')');
let meta = {}; try { meta = JSON.parse(c.metadados || '{}'); } catch (e) {}
const handle = String(meta.handle || meta.infinite_tag || c.conta_conectada || '').trim().replace(/^[$@]/, '');
if (!/^[A-Za-z0-9._-]{2,64}$/.test(handle)) return bad('PENDENTE_CONFIGURACAO_INFINITEPAY: InfiniteTag (handle) não identificada na credencial (metadados.handle ou conta_conectada)');

const e = $('Valida webhook').first().json;
return [{ json: { ok: true, payload: { handle, order_nsu: e.op_id, transaction_nsu: e.transaction_nsu, slug: e.slug } } }];

const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const j = $input.first().json; const e = $('Valida webhook').first().json;
if (!(j.success === true && j.paid === true)) return wfail(400, 'Pagamento não confirmado pela InfinitePay');
const valorCent = (j.paid_amount === undefined || j.paid_amount === null) ? null : Math.round(Number(j.paid_amount));
if (e.valor_webhook !== null && valorCent !== null && Number.isFinite(e.valor_webhook) && Math.round(e.valor_webhook) !== valorCent) return wfail(400, 'Valor do webhook diverge do valor confirmado pela InfinitePay');
return [{ json: { ok: true, op_id: e.op_id, transaction_nsu: e.transaction_nsu, slug: e.slug, valorCent, capture_method: j.capture_method || e.capture_method, payload: e.payload } }];

const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const p = $('Confirma pagamento').first().json;
const v = $('Ritmo — Venda (POS Invoice)').first().json; const ev = $input.first().json;
if (v.statusCode !== 200) return wfail(400, 'Falha ao consultar a venda no Ritmo (HTTP ' + v.statusCode + ') — webhook NÃO reconhecido, a InfinitePay reenviará');
if (ev.statusCode !== 200 && ev.statusCode !== 404) return wfail(400, 'Falha ao consultar o evento no Ritmo (HTTP ' + ev.statusCode + ') — webhook NÃO reconhecido, a InfinitePay reenviará');
const venda = ((v.body && v.body.data) || [])[0] || null;
const evento = ev.statusCode === 200 ? ev.body.data : null;
const total = venda ? Number(venda.rounded_total || venda.grand_total || 0) : null;
// A venda corresponde se existe (não cancelada) e o valor confere com o confirmado pela InfinitePay (tolerância de 1 centavo)
const achou = !!venda && venda.docstatus !== 2;
const confere = achou && (p.valorCent === null || Math.abs(Math.round(total * 100) - p.valorCent) <= 1);
const agora = new Date().toISOString().slice(0, 19).replace('T', ' ');           // UTC, formato Datetime do Frappe
const url = (n) => $env.ERPNEXT_DOMAIN.replace(/\/+$/, '') + '/api/resource/Synapse%20Evento%20Pagamento' + (n ? '/' + encodeURIComponent(n) : '');
const out = (status, http, req, extra) => [{ json: Object.assign({ ok: true, status, http, req }, extra || {}) }];
if (!evento) {                                                                  // primeiro webhook deste op_id
  const novo = { op_id: p.op_id, transaction_nsu: p.transaction_nsu, invoice_slug: p.slug, created_at: agora, valor: p.valorCent === null ? null : p.valorCent / 100, capture_method: p.capture_method, payload: p.payload };
  if (confere) return out('RECONCILED', 200, { method: 'POST', url: url(), body: Object.assign(novo, { status: 'RECONCILED', pos_invoice: venda.name, reconciled_at: agora }) });
  return out('PENDING_MATCH', 202, { method: 'POST', url: url(), body: Object.assign(novo, { status: 'PENDING_MATCH', observacao: achou ? 'Venda encontrada com valor divergente do pagamento' : null }) });
}
const divergente = evento.transaction_nsu !== p.transaction_nsu;                // mesmo op_id, outro transaction_nsu: não sobrescreve
const obs = 'transaction_nsu divergente recebido: ' + p.transaction_nsu;
const marcaDiv = divergente && !String(evento.observacao || '').includes(obs) ? { method: 'PUT', url: url(evento.name), body: { observacao: obs } } : null;
if (evento.status === 'RECONCILED' || evento.status === 'EXPIRED') return out(evento.status, 200, marcaDiv, { divergencia: divergente });   // idempotente: não reprocessa
if (confere && !divergente) return out('RECONCILED', 200, { method: 'PUT', url: url(evento.name), body: { status: 'RECONCILED', pos_invoice: venda.name, reconciled_at: agora } });
return out('PENDING_MATCH', 202, marcaDiv, { divergencia: divergente });

const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const d = $('Decide').first().json; const r = $input.first().json;
const duplicadoEmCorrida = d.req.method === 'POST' && r.statusCode === 409;      // outra entrega gravou antes: o evento já existe (idempotente)
if (!(r.statusCode >= 200 && r.statusCode < 300) && !duplicadoEmCorrida) return wfail(400, 'Falha ao registrar o evento no Ritmo (HTTP ' + r.statusCode + ') — webhook NÃO reconhecido, a InfinitePay reenviará');
return [{ json: { status: d.http, body: Object.assign({ success: true, message: null, status: d.status }, d.divergencia ? { divergencia: true } : {}) } }];

const d = $input.first().json;
if (d.ok === false) return [{ json: { status: d.status, body: d.body } }];   // falha de validação/consulta já formatada em "Decide"
return [{ json: { status: d.http, body: Object.assign({ success: true, message: null, status: d.status }, d.divergencia ? { divergencia: true } : {}) } }];
